  "stuSess.penaltyChoiceRefund": "Възстановяване по използвания начин на плащане",
  "stuSess.penaltyChoiceRefundDesc": "За възстановяване на сумата (€{amount}) се свържете с info@tutlio.lt. Ако сте платили с карта, възстановяването може все пак да бъде стартирано автоматично чрез Stripe.",
  "stuSess.creditAvailable": "Наличен кредит",
  "stuSess.payWithCredit": "Плащане с кредит",
  "stuSess.creditAppliedSuccess": "Към баланса ви е добавен кредит от €{amount}, който автоматично ще се приспадне от цената на следващия ви урок.",
  "stuSess.refundContactNote": "За възстановяване на сумата се свържете с <a href=\"mailto:info@tutlio.lt\" class=\"text-amber-800 underline\">info@tutlio.lt</a>.",
  "stuSess.refundSuccessStripeNote": "<p class=\"text-emerald-900 text-sm mb-2\">Имате въпроси или проблеми? Свържете се с <a href=\"mailto:info@tutlio.lt\" class=\"underline font-medium\">info@tutlio.lt</a>.</p><p class=\"font-semibold text-emerald-900\">Възстановяването на сумата е стартирано чрез Stripe.</p><p class=\"text-emerald-800 mt-1\">Сумите по карта обикновено се възстановяват в рамките на около <strong>5–10 работни дни</strong> (срокът зависи от банката). Ако не получите сумата в обичайния срок, пишете на <a href=\"mailto:info@tutlio.lt\" class=\"text-emerald-900 underline font-medium\">info@tutlio.lt</a>.</p>",
  "stuSess.refundSuccessManualTutor": "<p>Изглежда, че този урок не е платен чрез Stripe в Tutlio (напр. с банков превод или в брой). Тук няма автоматично възстановяване на сумата.</p><p class=\"mt-2\">За да уговорите възстановяване, свържете се с преподавателя си <strong>{tutor}</strong> — използвайте имейла или данните от резервациите си или предоставените директно от преподавателя.</p>",
  "stuSess.refundSuccessManualOrg": "<p>Изглежда, че този урок не е платен чрез Stripe в Tutlio (напр. с банков превод или в брой). Тук няма автоматично възстановяване на сумата.</p><p class=\"mt-2\">Тъй като се обучавате чрез организация, свържете се с <strong>администратора на организацията</strong> (чрез преподавателя си или публикуваните контакти на организацията).</p>",
  "stuSess.refundTutorFallback": "вашия преподавател",
