  "landing.footerSolutions": "Решения",
  "landing.footerResources": "Ресурси",
  "landing.faq.whatIsQ": "Какво е Tutlio?",
  "landing.faq.whatIsA": "Tutlio е платформа за управление на преподавателската дейност, която помага на частни преподаватели и школи да управляват графици, плащания, комуникация с ученици и проследяване на уроци на едно място.",
  "landing.faq.whoForQ": "За кого е Tutlio?",
  "landing.faq.whoForA": "Tutlio е създадена за частни преподаватели, учители по музика, езикови преподаватели, преподаватели по математика, школи и образователни центрове от всякакъв размер.",
  "landing.faq.waitlistQ": "Как работи списъкът с чакащи ученици?",
  "landing.faq.waitlistA": "Когато ученик отмени урок, освободеният час автоматично се предлага на учениците в списъка на чакащите. Първият, който потвърди, получава мястото - така преподавателите не губят приходи от отмени.",
  "landing.faq.freeTrialQ": "Има ли безплатен пробен период?",
  "landing.faq.freeTrialA": "Да! Всеки нов акаунт автоматично получава 7 дни безплатно - без код. През пробния период не се начислява такса и можете да се откажете по всяко време.",
  "landing.faq.languagesQ": "Кои езици поддържа Tutlio?",
  "landing.faq.languagesA": "Tutlio е достъпна на {count} езика: {languages}.",
  "landing.faqTitle": "Често задавани въпроси",
  "landing.feature.digital-business-card": "Дигитална визитка",
  "landing.feature.digital-business-cardDesc": "Споделете една професионална страница, на която учениците могат да научат за вас, да видят актуални цени и свободни часове и веднага да заявят урок.",
  "featuresIndex.newBadge": "Ново",
  "feature.digital-business-card.pageTitle": "Дигитална визитка, която превръща интереса в заявки за уроци",
  "feature.digital-business-card.pageDesc": "Дайте на всеки потенциален ученик една добре оформена връзка с представянето си, уроците, цените, отзивите и актуалните свободни часове. Той избира урок и час веднага - вие спирате да губите запитвания в дълги разговори.",
  "feature.digital-business-card.detailsTitle": "Всичко, от което се нуждае бъдещият ученик, за да каже „да“",
  "feature.digital-business-card.oneLink": "Една връзка за цялата ви преподавателска дейност",
  "feature.digital-business-card.oneLinkDesc": "Заменете разпилените социални профили, ценоразписи и съобщения за записване с една страница, която можете да споделяте навсякъде.",
  "feature.digital-business-card.liveAvailability": "Свободни часове, които винаги са актуални",
  "feature.digital-business-card.liveAvailabilityDesc": "Свободните часове идват директно от календара ви в Tutlio, така че клиентите заявяват само часове, в които действително искате да преподавате.",
  "feature.digital-business-card.instantEnquiries": "Заявки за уроци, докато преподавате",
  "feature.digital-business-card.instantEnquiriesDesc": "Родител или ученик избира урок, формат и час, след което оставя данните си. Пълната заявка достига до вас без разговор за уговаряне на графика.",
  "feature.digital-business-card.professionalBrand": "Професионално първо впечатление",
  "feature.digital-business-card.professionalBrandDesc": "Покажете снимката си, подхода към преподаването, предметите, цените, потвърдените отзиви и фирмените цветове на страница, която изглежда отлично на всеки телефон.",
  "feature.digital-business-card.faq.whatShowsQ": "Какво мога да показвам на дигиталната си визитка?",
  "feature.digital-business-card.faq.whatShowsA": "Можете да представите себе си, предметите, форматите на уроците, публичните цени, свободните часове в календара, местоположението, езиците, връзките към социални мрежи и потвърдените отзиви от ученици.",
  "feature.digital-business-card.faq.howBookingWorksQ": "Клиентът записва ли веднага потвърден урок?",
  "feature.digital-business-card.faq.howBookingWorksA": "Клиентът избира урок и свободен час, след което изпраща пълна заявка за записване. Получавате я в Tutlio и можете да потвърдите новия ученик, преди урокът да бъде добавен в графика ви.",
  "feature.digital-business-card.faq.whereShareQ": "Къде да споделям страницата?",
  "feature.digital-business-card.faq.whereShareA": "Използвайте я в Instagram, TikTok, групи във Facebook, реклами, имейл подписи, съобщения и QR кодове. Една връзка остава актуална дори когато цените или календарът ви се променят.",
  "feature.digital-business-card.demo.eyebrow": "Интерактивен преглед за клиента",
  "feature.digital-business-card.demo.title": "Изпробвайте процеса на записване",
  "feature.digital-business-card.demo.desc": "Изберете урок и час по-долу. Това е лесният път, който новият клиент изминава чрез споделената ви връзка.",
  "feature.digital-business-card.demo.profile": "Преподавател по математика · 9–12 клас",
  "feature.digital-business-card.demo.available": "Приема нови ученици",
