  "landing.leadSuccess": "Благодарим ви! Ще се свържем с вас.",
  "orgTutorPolicy.title": "Вътрешни правила за преподаватели",
  "orgTutorPolicy.intro": "Моля, запознайте се с вътрешните правила на организацията, преди да използвате платформата.",
  "orgTutorPolicy.acceptBtn": "Разбирам",
  "orgTutorPolicy.viewBtn": "Преглед на вътрешните правила",
  "orgTutorPolicy.s1Title": "1. Общи положения",
  "orgTutorPolicy.s1Body": "Тези правила уреждат използването на платформата Tutlio („Платформата“) от вас като учител или преподавател („Преподавател“). Поканени сте да използвате Платформата от образователната агенция, училището или учебния център, който представлявате („Организацията“). Техническата поддръжка и обслужването на Платформата се осигуряват от MB Tutlio. С използването на акаунта си приемате тези Правила и Политиката за поверителност.",
  "orgTutorPolicy.s2Title": "2. Управление на акаунта и графиците",
  "orgTutorPolicy.s2Intro": "Платформата е създадена, за да не губите време в съгласуване на часовете за уроци с учениците.",
  "orgTutorPolicy.s2Link": "Уникална връзка: Получавате лична връзка за записване на уроци (според предметите, които преподавате), която учениците използват, за да планират уроци.",
  "orgTutorPolicy.s2Calendar": "Синхронизиране на календара: Свободното ви време зависи пряко от интеграцията с Google Calendar (2-посочна синхронизация). Вие лично носите отговорност показаното свободно време в календара да е точно и актуално. Платформата няма да позволява на учениците да записват часове, отбелязани като заети в календара ви.",
  "orgTutorPolicy.s2Security": "Сигурност на акаунта: Акаунтът ви е личен. Трябва да пазите данните си за вход и да не ги споделяте с трети страни.",
  "orgTutorPolicy.s3Title": "3. Отмяна на уроци и списък на чакащите",
  "orgTutorPolicy.s3Intro": "Платформата ви помага да запълните графика си и да избегнете празни часове:",
  "orgTutorPolicy.s3Auto": "Ако ученик отмени урок, Платформата автоматично изпраща известие (SMS/имейл) до други ученици от списъка ви на чакащите, като им предлага освободения час. Не се изисква допълнително действие от вас.",
  "orgTutorPolicy.s3Rules": "Правилата за отмяна на уроци (колко предварително може да се отмени урок и какви са последствията) се определят от вашата Организация.",
  "orgTutorPolicy.s4Title": "4. Финанси и плащания",
  "orgTutorPolicy.s4Intro": "Не е необходимо да се грижите за фактурирането или събирането на плащания от родителите:",
  "orgTutorPolicy.s4Advance": "Всички плащания от ученици (или родители) за вашите уроци се събират предварително чрез Платформата и се превеждат директно на вашата Организация.",
  "orgTutorPolicy.s4Confirmed": "Провеждате урок само когато е потвърден в системата (което означава, че вече е таксуван).",
  "orgTutorPolicy.s4Contact": "За възнаграждението си, графика на изплащане и други финансови въпроси се обръщайте директно към администратора на вашата Организация. MB Tutlio не извършва преки финансови операции с Преподавателите.",
  "orgTutorPolicy.s5Title": "5. Защита на данните на учениците (GDPR)",
  "orgTutorPolicy.s5Intro": "Като Преподавател имате достъп до лични данни на учениците, вътрешни бележки и учебни материали. Поемате ангажимент да:",
  "orgTutorPolicy.s5Use": "Използвате тези данни единствено за организиране и провеждане на уроци.",
  "orgTutorPolicy.s5NoCopy": "Не копирате, изнасяте или разпространявате данни за контакт на ученици или родители извън Платформата.",
  "orgTutorPolicy.s5Notes": "Защитавате вътрешните записи на Организацията (бележки за напредъка на учениците), които са видими само за вас и администрацията на Организацията, но не и за учениците или родителите.",
  "orgTutorPolicy.s5Termination": "При прекратяване на работните ви отношения с Организацията достъпът ви до тези данни ще бъде отнет незабавно.",
  "orgTutorPolicy.s6Title": "6. Техническо функциониране и ограничаване на отговорността",
  "orgTutorPolicy.s6Body": "Забранено е използването на Платформата за незаконни цели, разпространяването на злонамерени връзки в учебните материали или друго нарушаване на работата на системата. MB Tutlio осигурява функционирането и техническата поддръжка на Платформата, но не носи отговорност за прекъсвания, причинени от вашата интернет връзка, неизправности на устройства или неправилни настройки на Google Calendar.",
  "orgTutorPolicy.s7Title": "7. Поддръжка и контакти",
  "orgTutorPolicy.s7Org": "За въпроси относно графиците на уроците, възнагражденията, разпределянето на ученици или организацията на работата се обръщайте към администратора на вашата Организация.",
  "orgTutorPolicy.s7Tech": "При технически грешки в Платформата (неработеща синхронизация на календара, неполучени известия) уведомете администратора на вашата Организация, който ще се свърже с екипа за техническа поддръжка на Tutlio.",
  "register.orgPolicyConsent": "С използването на платформата ни приемате",
  "register.orgPolicyLink": "вътрешните правила",
