  "quiz.info.story.solo.body": "Два кратки примера как едно свързано работно пространство може да промени седмицата на самостоятелен преподавател.",
  "quiz.info.story.solo.disclosure": "Илюстративни преживявания на преподаватели",
  "quiz.info.story.solo.name1": "Rasa",
  "quiz.info.story.solo.role1": "Преподавател по математика",
  "quiz.info.story.solo.story1": "„Когато уроците, данните за учениците и плащанията са на едно място, вече не прекарвам петъчната вечер във възстановяване на седмицата от съобщения.“",
  "quiz.info.story.solo.name2": "Mantas",
  "quiz.info.story.solo.role2": "Преподавател по английски",
  "quiz.info.story.solo.story2": "„Ясният календар и напомнянията ми позволяват да се съсредоточа върху подготовката на отлични уроци, вместо да повтарям една и съща административна работа.“",
  "quiz.info.story.company.eyebrow": "От клиент на Tutlio",
  "quiz.info.story.school.eyebrow": "От клиент на Tutlio",
  "quiz.info.story.company.title": "Какво се промени за екипа на PRO KLASĖ",
  "quiz.info.story.company.body": "Тяхната настройка обединява графиците, проследяването след уроци и индивидуалните правила за възнаграждение в един ежедневен работен процес.",
  "quiz.info.story.company.disclosure": "Работен процес на клиент",
  "quiz.info.story.school.disclosure": "Работен процес на клиент",
  "quiz.info.story.company.brandAlt": "Лого на PRO KLASĖ",
  "quiz.info.story.company.customerName": "PRO KLASĖ",
  "quiz.offer.testimonial.company.name1": "PRO KLASĖ",
  "quiz.info.story.company.customerType": "Екип на учебна организация",
  "quiz.offer.testimonial.company.role1": "Екип на учебна организация",
  "quiz.info.story.company.story": "„Преди Tutlio промените в уроците, коментарите и часовете на преподавателите бяха разпилени в съобщения. Сега целият екип работи по един и същи график и не се налага да издирваме актуализациите в края на месеца.“",
  "quiz.info.story.company.proof1": "Планиране на графика на екипа",
  "quiz.info.story.company.proof2": "Индивидуални правила за възнаграждение",
  "quiz.info.story.company.proof3": "Контрол на уроците",
  "quiz.info.story.company.detail": "„Най-голямата разлика беше, че одобренията, компенсаторните уроци и правилата за възнаграждение се съобразиха с начина, по който екипът ни вече работи, вместо да ни принуждават да следваме общ процес.“",
  "quiz.info.story.school.title": "Какво се промени за VšĮ “Laisvi vaikai”",
  "quiz.info.story.school.body": "Екипът им свързва данните на учениците, договорите, вноските и счетоводството в един административен процес.",
  "quiz.info.story.school.brandAlt": "Лого на VšĮ “Laisvi vaikai”",
  "quiz.info.story.school.customerName": "VšĮ “Laisvi vaikai”",
  "quiz.offer.testimonial.school.name1": "VšĮ “Laisvi vaikai”",
  "quiz.info.story.school.customerType": "Училищен административен екип",
  "quiz.offer.testimonial.school.role1": "Училищен административен екип",
  "quiz.info.story.school.story": "„Искахме едно място, където екипът да проследява всяко семейство от записването и договора до всяка вноска. Tutlio ни дава тази последователност, без да поддържаме паралелни таблици.“",
  "quiz.info.story.school.proof1": "Договори и подписи",
  "quiz.info.story.school.proof2": "Графици на вноски",
  "quiz.info.story.school.proof3": "Експорт за счетоводството",
  "quiz.info.story.school.detail": "„Най-ясното подобрение е, че виждаме статуса на договора, подписа и плащането, без да питаме няколко души или да проверяваме отделни файлове.“",
  "quiz.offer.testimonial.school.copy1": "„Най-ясното подобрение е, че виждаме статуса на договора, подписа и плащането, без да питаме няколко души или да проверяваме отделни файлове.“",
  "quiz.businessCard.eyebrow": "Вашата вградена страница за развитие",
