  "quiz.businessCard.body": "Дигиталната ви визитка в Tutlio дава на потенциалните ученици едно ясно място, където да разберат предложението ви, да видят свободните часове и да резервират урок.",
  "quiz.businessCard.previewAlt": "Преглед на дигитална визитка и страница за записване на уроци в Tutlio",
  "quiz.businessCard.benefitsLabel": "Предимства на дигиталната визитка",
  "quiz.businessCard.benefit1.title": "Споделяйте една връзка навсякъде",
  "quiz.businessCard.benefit1.body": "Използвайте я в реклами, социални профили, съобщения или имейл подписа си.",
  "quiz.businessCard.benefit2.title": "Улеснете решението",
