  "quiz.offer.guarantee.body": "Ако Tutlio не е подходяща за вас, поискайте възстановяване на сумата в рамките на първите 14 дни. Без въпроси.",
  "quiz.offer.testimonials.eyebrow": "Tutlio в ежедневната работа",
  "quiz.offer.testimonials.title.solo": "Какво забелязват самостоятелните преподаватели",
  "quiz.offer.testimonials.title.company": "Как Tutlio подпомага учебна организация",
  "quiz.offer.testimonials.title.school": "Как Tutlio свързва училищната администрация",
  "quiz.offer.testimonials.pause": "Пауза на отзивите",
  "quiz.offer.testimonials.play": "Пускане на отзивите",
  "quiz.offer.testimonials.navigation": "Изберете отзив",
  "quiz.offer.testimonials.goTo": "Показване на отзив {number}",
  "quiz.offer.testimonial.solo.name3": "Ieva",
  "quiz.offer.testimonial.solo.role3": "Преподавател по химия и биология",
  "quiz.offer.testimonial.solo.copy3": "„Публичната страница и записването чрез една връзка помагат на новите ученици да решат по-бързо, а аз вече не изпращам една и съща информация на всеки поотделно.“",
  "quiz.offer.testimonial.solo.name4": "Lukas",
  "quiz.offer.testimonial.solo.role4": "Преподавател по физика",
  "quiz.offer.testimonial.solo.copy4": "„Виждам веднага уроците, промените и статусите на плащанията в календара. Ежедневната администрация стана много по-кратка и ясна.“",
  "quiz.offer.testimonial.company.copy1": "„Промените в уроците, коментарите на преподавателите и часовете идваха в отделни съобщения. Сега административният екип вижда цялата картина в един график.“",
  "quiz.offer.testimonial.company.name2": "Независим учебен център",
  "quiz.offer.testimonial.company.role2": "Собственик · 8 преподаватели",
  "quiz.offer.testimonial.company.copy2": "„Прекарвах петъчните вечери в сравняване на календара със съобщенията на преподавателите, преди да подготвя възнагражденията. С Tutlio повечето проверки вече са направени.“",
  "quiz.offer.testimonial.company.name3": "Езиково учебно студио",
  "quiz.offer.testimonial.company.role3": "Оперативен ръководител · 14 преподаватели",
  "quiz.offer.testimonial.company.copy3": "„Когато урок се премести, екипът вижда една и съща актуализация веднага. Имаме по-малко последващи съобщения, а родителите получават много по-ясни отговори.“",
  "quiz.offer.testimonial.company.name4": "Академия за подготовка за изпити",
  "quiz.offer.testimonial.company.role4": "Финансов координатор · 22 преподаватели",
  "quiz.offer.testimonial.company.copy4": "„Правилата ни за възнаграждение на преподавателите зависят от вида на урока, затова краят на месеца изискваше много ръчни проверки. Процесът в Tutlio направи това много по-спокойно.“",
  "quiz.offer.testimonial.school.name2": "Независимо общностно училище",
  "quiz.offer.testimonial.school.role2": "Координатор по приема · 86 ученици",
  "quiz.offer.testimonial.school.copy2": "„Периодът на записване означаваше проследяване на формуляри, родителски данни и подписани договори в отделни папки. Сега екипът ни проследява всяко семейство от едно място.“",
  "quiz.offer.testimonial.school.name3": "Център за извънкласно обучение",
  "quiz.offer.testimonial.school.role3": "Администратор · 120 ученици",
  "quiz.offer.testimonial.school.copy3": "„Графиците на вноските направиха проследяването на плащанията много по-спокойно. Виждам какво се дължи, преди да се свържа с родител, вместо да съставям списъка ръчно.“",
  "quiz.offer.testimonial.school.name4": "Училище по изкуства",
  "quiz.offer.testimonial.school.role4": "Финансов координатор · 9 програми",
  "quiz.offer.testimonial.school.copy4": "„Експортът за счетоводството вече идва от същите записи, които използваме за договорите и плащанията, така че в края на месеца има много по-малко корекции.“",
  "quiz.offer.savings.eyebrow": "Приблизителен ефект върху времето",
  "quiz.offer.savings.subtitle": "Приблизително намаляване на повтарящата се административна работа, когато тези процеси са свързани чрез Tutlio.",
  "quiz.offer.savings.totalLabel": "потенциално намаляване на повтарящата се администрация",
  "quiz.offer.savings.listLabel": "Приблизително намаляване на администрацията по процеси",
