  "schoolsLanding.faq.whatIsQ": "Какво е Tutlio за училища?",
  "schoolsLanding.faq.whatIsA": "Tutlio Schools е софтуер за управление на школи - график на учителите, CRM за ученици, договори, плащания и отчети в една платформа.",
  "schoolsLanding.faq.whoForQ": "За кого е Tutlio Schools?",
  "schoolsLanding.faq.whoForA": "За езикови школи, центрове за частни уроци, музикални школи, програми за подготовка за изпити и всяка организация, която управлява много преподаватели и ученици.",
  "schoolsLanding.faq.contractsQ": "Можем ли да управляваме договори и плащания?",
  "schoolsLanding.faq.contractsA": "Да. Платформата поддържа шаблони за договори, електронно подписване, плащане на вноски, плащания чрез Stripe и финансови отчети.",
  "schoolsLanding.faq.pricingQ": "Как се формира цената за училища?",
