  "landing.custom.badge": "Голямата разлика",
  "landing.custom.title": "Софтуер, който се приспособява към начина, по който работите - а не обратното",
  "landing.custom.sub": "Всяко училище и всяка агенция работи малко по-различно. Когато стандартният процес не пасва, приспособяваме Tutlio към вашия - обикновено за седмици, не за тримесечия. Ето някои неща, които вече сме изградили за клиенти:",
  "landing.custom.ex1Title": "Годишни договори с електронен подпис",
  "landing.custom.ex1Desc": "Едно частно училище имаше нужда родителите да подписват годишните договори електронно, да плащат на вноски и всяко плащане да се вижда в експорт, готов за счетоводството. Днес целият цикъл се случва в Tutlio.",
  "landing.custom.ex2Title": "Правила за възнаграждение и комисиона на преподавателите",
  "landing.custom.ex2Desc": "Една агенция плаща на всеки преподавател според предмета и вида урок, като добавя фирмена комисиона. Моделирахме правилата им, така че месечните справки на преподавателите и фактурите се създават автоматично.",
  "landing.custom.ex3Title": "Оферти за родителите с едно щракване",
  "landing.custom.ex3Desc": "Едно училище искаше да предлага допълнителни уроци по имейл и родителите да ги приемат с едно щракване - без профил и без разпечатки. Приемането, фактурирането и поканата за първия урок вече вървят сами.",
  "landing.custom.ex4Title": "Вашата марка на вашия сайт",
  "landing.custom.ex4Desc": "Една организация искаше собствено лого и цветове, както и вход, вграден в нейния сайт, така че учениците и родителите никога да не усещат, че са го напуснали. Днес Tutlio работи под тяхната марка.",
  "landing.custom.note": "Нищо от това не е специално издание. Всяка адаптация става част от същия продукт, който екипът ви вече използва, заедно с всички бъдещи обновления.",
  "landing.custom.cta": "Разкажете ни как работите",
  "landing.custom.soloTitle": "Липсва ли ви нещо?",
  "landing.custom.soloNote": "Редовно разработваме функции за отделни клиенти - от едно правило за плащане до цял работен процес. Кажете ни какво би ви спестило време.",
